import { readFileSync, writeFileSync } from "fs";
import { resolve } from "path";
const root = resolve(import.meta.dir, "..");
const text =
  "// Generated by scripts/generate_completions.ts; edit completions/ instead.\n" +
  `export const bashCompletion = ${JSON.stringify(readFileSync(resolve(root, "completions/bpl-completion.bash"), "utf8"))};\n` +
  `export const zshCompletion = ${JSON.stringify(readFileSync(resolve(root, "completions/_bpl"), "utf8"))};\n`;
const output = resolve(root, "cli/completions/scripts.generated.ts");
if (process.argv.includes("--check")) {
  if (readFileSync(output, "utf8") !== text)
    throw new Error(
      "Run bun scripts/generate_completions.ts to refresh embedded completions.",
    );
} else writeFileSync(output, text);
